exercises.solution:
export function coresBusy(qps, cpuMsPerRequest) {
  return (qps * cpuMsPerRequest) / 1000;
}

export function instancesToBuy(qps, cpuMsPerRequest, coresPerInstance, headroomPct) {
  return Math.ceil((qps * cpuMsPerRequest * (100 + headroomPct)) / (100000 * coresPerInstance));
}

