exercises.solution:
export function desiredInstances(current, utilPermille, targetPermille) {
  return Math.ceil((current * utilPermille) / targetPermille);
}

export function minutesToScaleOut(current, needed, maxAddPerStep, cooldownMinutes) {
  return Math.max(0, Math.ceil((needed - current) / maxAddPerStep) * cooldownMinutes);
}

