exercises.solution:
export function replicaReadCapacity(perReplicaQps, writeQps) {
  return perReplicaQps - writeQps;
}

export function replicasNeeded(readQps, perReplicaQps, writeQps) {
  return Math.ceil(readQps / (perReplicaQps - writeQps));
}

