exercises.solution:
export function iopsNeeded(qps, pagesPerQuery, cacheHitPermille) {
  return (qps * pagesPerQuery * (1000 - cacheHitPermille)) / 1000;
}

export function maxQpsWithinIops(iopsLimit, pagesPerQuery, cacheHitPermille) {
  return (iopsLimit * 1000) / (pagesPerQuery * (1000 - cacheHitPermille));
}

