exercises.solution:
export function poolPerInstance(dbMaxConnections, reservedConnections, instances) {
  return Math.floor((dbMaxConnections - reservedConnections) / instances);
}

export function connectionsOverCommit(dbMaxConnections, reservedConnections, instances, poolSize) {
  return Math.max(0, instances * poolSize - (dbMaxConnections - reservedConnections));
}
